"""Print the ten most frequent words in a text file.

Usage: python wordfreq.py <file>

Words are compared case-insensitively and punctuation is ignored.
"""
import re
import sys
from collections import Counter


def main() -> None:
    if len(sys.argv) != 2:
        sys.exit(f"usage: python {sys.argv[0]} <textfile>")

    try:
        with open(sys.argv[1], encoding="utf-8") as f:
            text = f.read()
    except OSError as e:
        sys.exit(f"error: cannot read {sys.argv[1]!r}: {e}")

    words = re.findall(r"[a-z']+", text.lower())
    if not words:
        sys.exit("error: no words found in the file")

    counts = Counter(words)
    for word, count in counts.most_common(10):
        print(f"{count:>4}  {word}")


if __name__ == "__main__":
    main()
